//! Exact code-unit named reads use actual native associated-element attributes.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><p id=target></p><svg id=svg></svg></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://dataset-raw.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn dataset_raw_named_read_exact_surrogate_identity_and_live_attributes(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset;for(var k of ['a\ud800Z','a\udfffZ','\ud800','\udfff','pair\ud800\ud800','x\ud800\ufffd']){var attr='data-'+k.replace('Z','-z');n.setAttributeNS(null,attr,'v'+k);if(d[k]!=='v'+k)throw 'exact raw key';n.setAttributeNS(null,attr,'changed');if(d[k]!=='changed')throw 'live replacement';n.removeAttributeNS(null,attr);if(d[k]!==undefined)throw 'live removal';}n.setAttributeNS(null,'data-x\ud800','raw');n.setAttributeNS(null,'data-x\ufffd','scalar');if(d['x\ud800']!=='raw'||d['x\ufffd']!=='scalar')throw 'projection collision';"#);}

#[test]
fn dataset_raw_named_read_ascii_conversion_namespace_and_svg_membership(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"for(var n of [document.getElementById('target'),document.getElementById('svg')]){var d=n.dataset;n.setAttributeNS(null,'data-a-\ud800-b','native');if(n===document.getElementById('target'))n.setAttributeNS('urn:foreign','q:data-a\ud800','foreign');n.setAttributeNS(null,'data-UP\ud800','excluded');if(d['a-\ud800B']!=='native'||d['a-\ud800-b']!==undefined||d['a\ud800']!==undefined||d['UP\ud800']!==undefined)throw 'namespace and ASCII supported-name rules';n.setAttributeNS(null,'data-a\ud800','actual');if(d['a\ud800']!=='actual')throw 'real null namespace';}"#);}

#[test]
fn dataset_raw_named_read_native_overrides_author_prototype_and_missing_falls_back(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,p=DOMStringMap.prototype,hits=0;Object.defineProperty(p,'a\ud800B',{get:function(){hits++;if(this!==d)throw 'receiver';return 'inherited';},configurable:true});if(d['a\ud800B']!=='inherited'||hits!==1)throw 'missing prototype fallback';n.setAttributeNS(null,'data-a\ud800-b','native');if(d['a\ud800B']!=='native'||hits!==1)throw 'LegacyOverrideBuiltIns';n.removeAttributeNS(null,'data-a\ud800-b');if(d['a\ud800B']!=='inherited'||hits!==2)throw 'live inherited restoration';delete p['a\ud800B'];if(d['a\ud800B']!==undefined)throw 'deleted author prototype';"#);}

#[test]
fn dataset_raw_named_read_preserves_raw_value_and_no_author_conversion(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target'),d=n.dataset,calls=0,key={toString:function(){calls++;return 'x\ud800';}};n.setAttributeNS(null,'data-x\ud800','a\udfffZ');if(d[key]!=='a\udfffZ'||calls!==1||n.getAttributeNS(null,'data-x\ud800')!=='a\udfffZ'||d['x\ufffd']!==undefined)throw 'raw value and once key binding';var sentinel={};try{d[{toString:function(){throw sentinel;}}];throw 'missing abrupt';}catch(e){if(e!==sentinel)throw 'abrupt identity';}if(d['x\ud800']!=='a\udfffZ')throw 'recovery';"#);}

#[test]
fn dataset_raw_named_read_native_work_deadline_refusal_unchanged_and_recovery(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var n=document.getElementById('target');n.setAttributeNS(null,'data-x\ud800','value');"#);let node=(0..d.nodes.len()).find(|&n|d.attr(n,"id")==Some("target")).unwrap();let handle=DATASET_BASE+node as u32;let units=[120,0xd800];let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;for expired in [false,true]{p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}let error=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.named_units_property(handle,&units).unwrap_err();assert!(!error.is_empty());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.state.execution_deadline=None;p.begin_job();let value=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.named_units_property(handle,&units).unwrap();assert!(matches!(value,Some(Value::String(v))if v=="value"));}}
